/* ---------- Pologne, Europe centrale, pays baltes, Ukraine ---------- */
const D35 = [
{ id:'bigos', c:'eu', lat:52.230, lon:21.012, base:8, prep:40, cook:240, diff:2, tags:['slow','pork','comfort'],
  art:{v:'pot',bg:'#2b2419',plate:'#eee0bc',style:'stew',food:['#8f6a4a','#c9a878','#6f4a2a','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Bigos',en:'Bigos'},
  p:{fr:'Varsovie, Pologne',en:'Warsaw, Poland'},
  d:{fr:"Le « ragoût du chasseur » : choucroute, chou frais, plusieurs viandes et des prunes séchées, mijotés puis réchauffés trois jours de suite. Mickiewicz lui consacre vingt vers dans Pan Tadeusz — c'est dire.",
     en:"The 'hunter's stew': sauerkraut, fresh cabbage, several meats and dried plums, stewed then reheated three days running. Mickiewicz gives it twenty lines in Pan Tadeusz — which says something."},
  i:[['sauerkraut',1,'kg'],['cabbage',500,'g'],['pork_shoulder',500,'g'],['smoked_sausage',400,'g'],['smoked_bacon',200,'g'],['onion',3,'pc'],['prunes',150,'g'],['dried_morels',20,'g'],['tomato_paste',3,'tbsp'],['red_wine',250,'ml'],['juniper_berries',10,'pc'],['bay_leaf',3,'pc'],['allspice',6,'pc'],['lard',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Rincez la choucroute si elle est très acide, pressez-la et hachez-la ; émincez le chou frais.","Faites revenir le lard et l'oignon dans le saindoux, puis colorez le porc en gros cubes et la saucisse en rondelles.","Réunissez tout dans une grande cocotte avec les champignons trempés, les pruneaux, le vin, le concentré et les épices.","Laissez mijoter 3 heures à feu très doux, en remuant de temps en temps pour que rien n'attache.","Laissez refroidir, puis réchauffez-le le lendemain et le surlendemain : le bigos ne devient lui-même qu'au troisième jour."],
     en:["Rinse the sauerkraut if it is very sour, squeeze it dry and chop it; shred the fresh cabbage.","Fry the bacon and onion in the lard, then brown the pork in large cubes and the sausage in rounds.","Bring everything together in a large pot with the soaked mushrooms, prunes, wine, tomato paste and spices.","Simmer for 3 hours over very low heat, stirring now and then so nothing catches.","Let it cool, then reheat it the next day and the day after: bigos only becomes itself on the third day."]} },

{ id:'zurek', c:'eu', lat:50.049, lon:19.945, base:6, prep:20, cook:60, diff:2, tags:['soup','pork','festive'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f2ead6',style:'soup',food:['#f0e8d0','#e8dcc0','#c9a878','#f4f0e6'],garnish:'#7fae6a'},
  n:{fr:'Żurek',en:'Żurek'},
  p:{fr:'Cracovie, Pologne',en:'Kraków, Poland'},
  d:{fr:"Une soupe aigre au levain de seigle fermenté cinq jours, servie à Pâques avec de la saucisse blanche et un œuf dur. L'acidité vient d'une fermentation lactique domestique que chaque famille entretenait dans un pot de grès.",
     en:"A sour soup made from rye starter fermented for five days, served at Easter with white sausage and a hard-boiled egg. The sourness comes from a household lactic ferment once kept in a stoneware crock."},
  i:[['rye_flour',150,'g'],['warm_water',500,'ml'],['garlic',6,'clove'],['smoked_bacon',150,'g'],['white_sausage',500,'g'],['onion',2,'pc'],['marjoram',2,'tbsp'],['horseradish',2,'tbsp'],['heavy_cream',200,'ml'],['egg',6,'pc'],['bay_leaf',2,'pc'],['allspice',5,'pc'],['potato',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Cinq jours à l'avance, mêlez la farine de seigle, l'eau tiède et deux gousses d'ail dans un bocal ; couvrez d'un linge et laissez fermenter à température ambiante.","Le jour même, faites un bouillon avec le lard, l'oignon, le laurier et le piment de la Jamaïque, 40 minutes.","Pochez-y les saucisses blanches 20 minutes, retirez-les et coupez-les en rondelles.","Secouez le levain, versez-le dans le bouillon en filet et laissez cuire 10 minutes sans bouillir : il s'éclaircit et lie la soupe.","Ajoutez crème, marjolaine, raifort et ail écrasé. Servez avec les saucisses, un demi-œuf dur et des pommes de terre."],
     en:["Five days ahead, mix the rye flour, warm water and two garlic cloves in a jar; cover with a cloth and ferment at room temperature.","On the day, make a broth with the bacon, onion, bay and allspice for 40 minutes.","Poach the white sausages in it for 20 minutes, lift them out and cut into rounds.","Shake the starter, pour it into the broth in a thin stream and cook for 10 minutes without boiling: it clears and thickens the soup.","Add cream, marjoram, horseradish and crushed garlic. Serve with the sausage, half a hard-boiled egg and potatoes."]} },

{ id:'barszcz-czerwony', c:'eu', lat:52.407, lon:16.925, base:6, prep:30, cook:75, diff:2, tags:['soup','veg','festive'],
  art:{v:'bowl',bg:'#2c2434',plate:'#f2ead6',style:'soup',food:['#8f1a3a','#a8203a','#c9402c','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Barszcz rouge',en:'Red barszcz'},
  p:{fr:'Poznań, Pologne',en:'Poznań, Poland'},
  d:{fr:"Un bouillon de betterave clair comme du vin, servi brûlant dans une tasse le soir de Noël, avec de petits raviolis aux champignons. Rien à voir avec le bortsch ukrainien : celui-ci est filtré, limpide, presque une boisson.",
     en:"A beetroot broth as clear as wine, served scalding in a cup on Christmas Eve with tiny mushroom dumplings. Nothing like Ukrainian borscht: this one is strained, limpid, almost a drink."},
  i:[['beetroot',1.2,'kg'],['carrot',2,'pc'],['celery_root',1,'pc'],['leek',1,'pc'],['dried_morels',30,'g'],['garlic',5,'clove'],['bay_leaf',3,'pc'],['allspice',6,'pc'],['red_wine_vinegar',60,'ml'],['sugar',1,'tbsp'],['marjoram',1,'tbsp'],['water',2,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les champignons séchés une heure et gardez précieusement leur eau.","Rôtissez la moitié des betteraves entières au four 50 minutes : c'est ce qui donne la profondeur au bouillon.","Faites bouillir l'autre moitié râpée avec les légumes, les épices et l'eau des champignons, 45 minutes à petit feu.","Filtrez très soigneusement à travers un linge, sans presser, pour garder la limpidité.","Rectifiez à l'aigre-doux avec le vinaigre et le sucre, ajoutez l'ail et la marjolaine, et servez brûlant en tasse."],
     en:["Soak the dried mushrooms for an hour and carefully keep their liquid.","Roast half the beetroot whole for 50 minutes: this is what gives the broth its depth.","Boil the other half, grated, with the vegetables, spices and mushroom liquid for 45 minutes over low heat.","Strain very carefully through a cloth, without pressing, to keep it clear.","Balance it sweet-sour with the vinegar and sugar, add the garlic and marjoram, and serve scalding in cups."]} },

{ id:'kotlet-schabowy', c:'eu', lat:52.237, lon:21.017, base:4, prep:20, cook:15, diff:1, tags:['pork','fry','sunday'],
  art:{v:'plate',bg:'#2f3326',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#f0d89a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Kotlet schabowy',en:'Kotlet schabowy'},
  p:{fr:'Varsovie, Pologne',en:'Warsaw, Poland'},
  d:{fr:"L'escalope de porc panée du dimanche polonais, servie avec des pommes de terre à l'aneth et une salade de chou. Elle doit déborder de l'assiette : c'est un critère, pas une exagération.",
     en:"The Sunday breaded pork chop of Poland, served with dill potatoes and a cabbage salad. It is supposed to hang over the edge of the plate: that is a criterion, not an exaggeration."},
  i:[['pork_loin',800,'g'],['flour',100,'g'],['egg',3,'pc'],['breadcrumbs',250,'g'],['lard',200,'g'],['potato',800,'g'],['dill',1,'bunch'],['cabbage',400,'g'],['carrot',1,'pc'],['sour_cream',150,'ml'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le filet en tranches de 2 cm et aplatissez-les au maillet jusqu'à 8 mm, en partant du centre vers l'extérieur.","Salez, poivrez, puis passez dans la farine, l'œuf battu et la chapelure, sans presser.","Faites chauffer le saindoux à hauteur d'un demi-centimètre et saisissez les escalopes 4 minutes par face, à feu moyen.","Secouez la poêle pendant la cuisson : la graisse doit passer sous la panure et la faire souffler.","Servez aussitôt avec les pommes de terre à l'aneth et une salade de chou râpé à la crème et au citron."],
     en:["Cut the loin into 2 cm slices and beat them out to 8 mm, working from the centre outwards.","Season, then coat in flour, beaten egg and breadcrumbs, without pressing.","Heat the lard half a centimetre deep and fry the cutlets 4 minutes a side over medium heat.","Shake the pan as they cook: the fat should run under the crumb and puff it up.","Serve at once with dill potatoes and a cabbage salad dressed with cream and lemon."]} },

{ id:'oscypek-grille', c:'eu', lat:49.299, lon:19.949, base:4, prep:10, cook:10, diff:1, tags:['cheese','grill','fast'],
  art:{v:'board',bg:'#33301f',plate:'#f0e2c0',style:'grill',food:['#e0b45a','#c98a2c','#8f1a3a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Oscypek grillé aux airelles',en:'Grilled oscypek with cranberry'},
  p:{fr:'Zakopane, Tatras, Pologne',en:'Zakopane, Tatras, Poland'},
  d:{fr:"Un fromage de brebis fumé, pressé dans des moules de bois sculptés en fuseau, grillé jusqu'à ce qu'il boursoufle et servi avec de la confiture d'airelles. Sa fabrication est protégée et réservée aux bergers des Tatras.",
     en:"A smoked ewe's-milk cheese pressed in carved wooden spindle moulds, grilled until it blisters and served with cranberry jam. Its making is protected and reserved to Tatra shepherds."},
  i:[['sheep_milk_cheese',600,'g'],['cranberry_jam',200,'g'],['olive_oil',2,'tbsp'],['rustic_bread',1,'pc'],['pepper',null,'']],
  s:{fr:["Tranchez le fromage fumé en morceaux d'un centimètre d'épaisseur, dans le sens de la longueur.","Huilez très légèrement la grille — le fromage colle facilement — et préparez une braise moyenne, jamais vive.","Grillez 3 minutes par face : la surface doit se strier et gonfler sans que le cœur ne coule.","Retirez dès que les bords s'affaissent : quelques secondes de trop et le fromage se répand dans les braises.","Servez brûlant avec une cuillerée de confiture d'airelles et du pain de campagne grillé."],
     en:["Slice the smoked cheese lengthways into pieces a centimetre thick.","Oil the grill very lightly — the cheese sticks easily — and prepare medium embers, never fierce ones.","Grill 3 minutes a side: the surface should stripe and swell without the centre running.","Take it off the moment the edges start to sag: a few seconds more and the cheese pours into the fire.","Serve scalding with a spoonful of cranberry jam and toasted country bread."]} },

{ id:'paczki', c:'eu', lat:53.013, lon:18.598, base:8, prep:120, cook:20, diff:2, tags:['sweet','fry','festive'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#8f1a3a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Pączki',en:'Pączki'},
  p:{fr:'Toruń, Pologne',en:'Toruń, Poland'},
  d:{fr:"Les beignets du Jeudi gras, fourrés à la confiture de rose ou aux prunes. La tradition veut qu'il faille en manger au moins un ce jour-là sous peine de malchance pour l'année : les Polonais en engloutissent cent millions.",
     en:"The doughnuts of Fat Thursday, filled with rose jam or plum. Tradition says you must eat at least one that day or face a year of bad luck: Poles get through a hundred million of them."},
  i:[['flour',600,'g'],['whole_milk',250,'ml'],['fresh_yeast',35,'g'],['egg_yolk',6,'pc'],['sugar',100,'g'],['butter',100,'g'],['dark_rum',3,'tbsp'],['rose_water',1,'tbsp'],['berry_jam',300,'g'],['frying_oil',1.5,'l'],['powdered_sugar',100,'g'],['orange_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Préparez un levain avec la levure, le lait tiède et un peu de farine ; laissez mousser 20 minutes.","Fouettez les jaunes avec le sucre jusqu'au ruban, puis pétrissez avec la farine, le levain, le rhum et le sel 15 minutes.","Incorporez le beurre mou en dernier et laissez lever 1 h 30 : la pâte doit être très souple.","Formez des boules de 60 g, garnissez chacune d'une cuillerée de confiture et refermez soigneusement ; laissez pousser 40 minutes.","Frites 2 minutes par face à 175 °C, à couvert pour la première face : c'est ce qui fait la ceinture pâle sur le pourtour."],
     en:["Make a starter with the yeast, warm milk and a little flour; let it froth for 20 minutes.","Whisk the yolks with the sugar to the ribbon, then knead with the flour, starter, rum and salt for 15 minutes.","Work in the soft butter last and prove for 1½ hours: the dough should be very slack.","Shape 60 g balls, fill each with a spoonful of jam and seal carefully; prove for 40 minutes.","Fry 2 minutes a side at 175°C, covered for the first side: that is what makes the pale ring around the middle."]} },

{ id:'vepro-knedlo-zelo', c:'eu', lat:49.746, lon:13.377, base:4, prep:40, cook:120, diff:2, tags:['pork','slow','sunday'],
  art:{v:'plate',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#f4f0e6','#c9a878','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Porc, knedlíky et chou',en:'Vepřo knedlo zelo'},
  p:{fr:'Plzeň, Bohême, Tchéquie',en:'Plzeň, Bohemia, Czechia'},
  d:{fr:"Le plat national tchèque tient en trois mots : rôti de porc, quenelles de pain tranchées au fil, chou aigre-doux au carvi. On le mange avec une bière de Plzeň, ce qui n'est pas facultatif.",
     en:"The Czech national dish comes in three words: roast pork, bread dumplings sliced with a thread, sweet-sour caraway cabbage. Eaten with a Plzeň beer, which is not optional."},
  i:[['pork_shoulder',1.2,'kg'],['caraway',2,'tbsp'],['garlic',6,'clove'],['onion',2,'pc'],['flour',500,'g'],['whole_milk',250,'ml'],['egg',2,'pc'],['fresh_yeast',15,'g'],['bread_roll',3,'pc'],['sauerkraut',700,'g'],['sugar',2,'tbsp'],['beer',300,'ml'],['lard',50,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Frottez le porc de sel, d'ail écrasé et de carvi, posez-le sur un lit d'oignons et arrosez de bière.","Enfournez 2 heures à 160 °C en arrosant régulièrement, puis 15 minutes à 220 °C pour la croûte.","Pour les knedlíky, pétrissez farine, lait tiède, levure, œufs et sel, incorporez les petits pains en dés, et laissez lever une heure.","Formez deux gros boudins et pochez-les 20 minutes dans l'eau frémissante, en les retournant à mi-cuisson. Tranchez-les au fil, jamais au couteau.","Faites revenir la choucroute avec l'oignon, le carvi et le sucre 30 minutes, et servez le tout arrosé du jus de rôti."],
     en:["Rub the pork with salt, crushed garlic and caraway, set it on a bed of onions and pour over the beer.","Roast for 2 hours at 160°C, basting regularly, then 15 minutes at 220°C for the crackling.","For the knedlíky, knead flour, warm milk, yeast, eggs and salt, work in the diced bread rolls, and prove for an hour.","Shape two large logs and poach them for 20 minutes in simmering water, turning halfway. Slice them with a thread, never a knife.","Fry the sauerkraut with onion, caraway and sugar for 30 minutes, and serve everything under the roasting juices."]} },

{ id:'kulajda', c:'eu', lat:48.975, lon:14.474, base:4, prep:20, cook:30, diff:1, tags:['soup','veg','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f4f0e6','#e8dcc0','#8f6a4a','#f0e8d0'],garnish:'#6fbf8f'},
  n:{fr:'Kulajda',en:'Kulajda'},
  p:{fr:'České Budějovice, Bohême du Sud',en:'České Budějovice, South Bohemia'},
  d:{fr:"Une soupe blanche de pommes de terre et de champignons, acidulée à la crème aigre et au vinaigre, avec un œuf poché posé dedans. L'aneth y est massif — c'est lui qui distingue la kulajda de toute autre soupe bohémienne.",
     en:"A white soup of potato and mushroom, sharpened with sour cream and vinegar, with a poached egg set in it. The dill is heavy-handed — that is what tells kulajda apart from any other Bohemian soup."},
  i:[['potato',600,'g'],['mushroom',300,'g'],['dill',1,'bunch'],['sour_cream',300,'ml'],['flour',2,'tbsp'],['white_vinegar',3,'tbsp'],['egg',4,'pc'],['caraway',1,'tsp'],['bay_leaf',2,'pc'],['butter',40,'g'],['sugar',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire les pommes de terre en dés dans un litre d'eau salée avec le carvi et le laurier.","Faites revenir les champignons émincés au beurre et ajoutez-les à la casserole à mi-cuisson.","Délayez la crème aigre avec la farine, versez-la en filet dans la soupe et laissez épaissir 5 minutes sans bouillir.","Pochez les œufs à part dans une eau vinaigrée, 3 minutes, jaune coulant.","Relevez la soupe au vinaigre, au sucre et à beaucoup d'aneth ciselé, puis déposez un œuf poché dans chaque assiette."],
     en:["Cook the diced potatoes in a litre of salted water with the caraway and bay.","Fry the sliced mushrooms in butter and add them to the pan halfway through.","Slacken the sour cream with the flour, stir it into the soup in a thin stream and thicken for 5 minutes without boiling.","Poach the eggs separately in vinegared water for 3 minutes, yolks running.","Sharpen the soup with vinegar, sugar and a great deal of chopped dill, then set a poached egg in each bowl."]} },

{ id:'trdelnik', c:'eu', lat:50.087, lon:14.421, base:8, prep:90, cook:15, diff:2, tags:['sweet','street','bake'],
  art:{v:'board',bg:'#2f2519',plate:'#f2e6c8',style:'roll',food:['#c9924a','#e0b45a','#f2dfa8','#8f6a4a'],garnish:'#c9754a'},
  n:{fr:'Trdelník',en:'Trdelník'},
  p:{fr:'Prague, Tchéquie',en:'Prague, Czechia'},
  d:{fr:"Un ruban de pâte enroulé autour d'un rouleau de bois, tourné au-dessus de la braise et roulé dans le sucre et les noix. Venu de Transylvanie au XVIIIe siècle, il a conquis les rues de Prague — au point d'y agacer les Pragois.",
     en:"A ribbon of dough wound around a wooden roller, turned over embers and rolled in sugar and nuts. It came from Transylvania in the 18th century and conquered the streets of Prague — to the irritation of Praguers."},
  i:[['flour',500,'g'],['whole_milk',250,'ml'],['fresh_yeast',25,'g'],['sugar',200,'g'],['egg',2,'pc'],['butter',100,'g'],['walnuts',150,'g'],['cinnamon',2,'tsp'],['vanilla',1,'tsp'],['salt',null,'']],
  s:{fr:["Préparez un levain avec la levure, le lait tiède et une cuillerée de sucre ; laissez mousser 15 minutes.","Pétrissez avec la farine, les œufs, 60 g de sucre, le beurre mou et le sel, 12 minutes, puis laissez lever une heure.","Détaillez des lanières de 2 cm de large et enroulez-les en spirale autour de rouleaux de bois beurrés, bords bien jointifs.","Badigeonnez de beurre fondu, roulez dans le sucre et faites tourner au-dessus de la braise 12 minutes, sans cesser de tourner.","Roulez encore chaud dans le mélange sucre, noix concassées et cannelle, puis faites glisser le cylindre hors du rouleau."],
     en:["Make a starter with the yeast, warm milk and a spoonful of sugar; let it froth for 15 minutes.","Knead with the flour, eggs, 60 g of sugar, the soft butter and salt for 12 minutes, then prove for an hour.","Cut 2 cm strips and wind them in a spiral around buttered wooden rollers, edges just touching.","Brush with melted butter, roll in sugar and turn over the embers for 12 minutes, never stopping.","While still hot, roll in the sugar, crushed walnut and cinnamon mixture, then slide the cylinder off the roller."]} },

{ id:'bramborak', c:'eu', lat:49.195, lon:16.608, base:4, prep:20, cook:20, diff:1, tags:['veg','fry','fast'],
  art:{v:'plate',bg:'#33301f',plate:'#f0e2c0',style:'flat',food:['#e0b45a','#c98a2c','#f2dfa8','#8f6a2b'],garnish:'#7fae6a'},
  n:{fr:'Bramborák',en:'Bramborák'},
  p:{fr:'Brno, Moravie, Tchéquie',en:'Brno, Moravia, Czechia'},
  d:{fr:"Une galette de pommes de terre râpées à l'ail et à la marjolaine, frite au saindoux jusqu'à devenir cassante. Vendue dans les fêtes de village avec un simple morceau de papier pour la tenir.",
     en:"A cake of grated potato with garlic and marjoram, fried in lard until brittle. Sold at village fairs with nothing but a scrap of paper to hold it."},
  i:[['potato',1,'kg'],['garlic',6,'clove'],['marjoram',2,'tbsp'],['egg',2,'pc'],['flour',80,'g'],['whole_milk',50,'ml'],['caraway',1,'tsp'],['lard',150,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Râpez les pommes de terre à la grille fine et laissez-les égoutter cinq minutes dans une passoire, sans presser.","Mêlez-les aux œufs, à la farine, au lait, à l'ail écrasé, à la marjolaine et au carvi.","Salez au dernier moment seulement, la pâte doit rester épaisse et à peine coulante.","Chauffez le saindoux et déposez des cuillerées aplaties de 12 cm ; laissez prendre 4 minutes sans y toucher.","Retournez, dorez 3 minutes de l'autre côté et égouttez sur une grille. Se mangent brûlantes, à la main."],
     en:["Grate the potatoes finely and let them drain in a colander for five minutes, without pressing.","Mix with the eggs, flour, milk, crushed garlic, marjoram and caraway.","Salt only at the last moment; the batter should stay thick and barely pourable.","Heat the lard and drop in flattened spoonfuls 12 cm across; let them set for 4 minutes untouched.","Turn, brown for 3 minutes on the other side and drain on a rack. Eaten scalding, with your fingers."]} },

{ id:'kapustnica', c:'eu', lat:48.720, lon:21.258, base:6, prep:30, cook:90, diff:1, tags:['soup','pork','festive'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'soup',food:['#c9754a','#e8dcb8','#8f5a3a','#e0913a'],garnish:'#7fae6a'},
  n:{fr:'Kapustnica',en:'Kapustnica'},
  p:{fr:'Košice, Slovaquie',en:'Košice, Slovakia'},
  d:{fr:"La soupe de choucroute du réveillon slovaque, avec saucisse fumée, champignons séchés et pruneaux. Chaque famille a la sienne ; certaines y ajoutent de la crème, d'autres crient au sacrilège.",
     en:"The sauerkraut soup of the Slovak Christmas Eve, with smoked sausage, dried mushrooms and prunes. Every family has its own; some add cream, others call that sacrilege."},
  i:[['sauerkraut',700,'g'],['smoked_sausage',400,'g'],['smoked_pork_ribs',400,'g'],['dried_morels',30,'g'],['prunes',100,'g'],['onion',2,'pc'],['garlic',4,'clove'],['sweet_paprika',1,'tbsp'],['flour',2,'tbsp'],['lard',50,'g'],['bay_leaf',2,'pc'],['allspice',5,'pc'],['sour_cream',200,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les champignons une heure, gardez l'eau de trempage.","Portez les côtes fumées à frémissement dans deux litres d'eau avec le laurier et le piment, 45 minutes.","Ajoutez la choucroute rincée et pressée, les champignons, leur eau, les pruneaux et la saucisse en rondelles ; poursuivez 30 minutes.","Préparez un roux blond de saindoux, farine et paprika, hors du feu, et versez-le dans la soupe pour la lier.","Effilochez la viande des os, remettez-la, rectifiez et servez avec une cuillerée de crème aigre — ou non, selon votre camp."],
     en:["Soak the mushrooms for an hour and keep the soaking liquid.","Bring the smoked ribs to a simmer in two litres of water with the bay and allspice for 45 minutes.","Add the rinsed and squeezed sauerkraut, the mushrooms with their liquid, the prunes and the sliced sausage; continue for 30 minutes.","Make a pale roux of lard, flour and paprika off the heat, and stir it into the soup to thicken it.","Pull the meat from the bones, return it, adjust the seasoning and serve with a spoonful of sour cream — or not, depending on your camp."]} },

{ id:'mamaliga-branza', c:'eu', lat:47.929, lon:23.887, base:4, prep:15, cook:40, diff:1, tags:['veg','cheese','comfort'],
  art:{v:'pot',bg:'#33301f',plate:'#eee0bc',style:'stew',food:['#e8c46a','#f4f0e6','#f2e0a8','#c9a24a'],garnish:'#7fae6a'},
  n:{fr:'Mămăligă au fromage et à la crème',en:'Mămăligă with cheese and cream'},
  p:{fr:'Sighetu Marmației, Maramureș, Roumanie',en:'Sighetu Marmației, Maramureș, Romania'},
  d:{fr:"La polenta roumaine, versée sur une planche et découpée au fil, servie avec du fromage de brebis salé, de la crème et un œuf. Elle a nourri les campagnes pendant deux siècles, quand le pain de blé était un luxe.",
     en:"Romanian polenta, poured onto a board and cut with a thread, served with salted sheep's cheese, cream and an egg. It fed the countryside for two centuries, when wheat bread was a luxury."},
  i:[['cornmeal',300,'g'],['water',1.2,'l'],['sheep_milk_cheese',250,'g'],['sour_cream',300,'ml'],['egg',4,'pc'],['butter',60,'g'],['smoked_bacon',100,'g'],['coarse_salt',1,'tbsp']],
  s:{fr:["Portez l'eau salée à ébullition et versez la semoule de maïs en pluie en fouettant sans arrêt.","Baissez le feu et remuez à la cuillère de bois 30 minutes, jusqu'à ce que la masse se détache des parois.","Renversez la mămăligă sur une planche de bois humide et laissez-la prendre deux minutes avant de la découper au fil.","Faites rissoler le lard en dés et cuisez les œufs au plat dans la graisse rendue.","Servez la mămăligă avec le fromage émietté, la crème aigre, l'œuf et les lardons croustillants."],
     en:["Bring the salted water to the boil and rain in the cornmeal, whisking constantly.","Lower the heat and stir with a wooden spoon for 30 minutes, until the mass pulls away from the sides.","Turn the mămăligă out onto a damp wooden board and let it firm for two minutes before cutting it with a thread.","Fry the diced bacon and cook the eggs in the rendered fat.","Serve the mămăligă with the crumbled cheese, sour cream, egg and crisp bacon."]} },

{ id:'ciorba-de-burta', c:'eu', lat:44.432, lon:26.106, base:6, prep:30, cook:180, diff:2, tags:['soup','slow','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#f0e8d0','#e8dcc0','#c9a878','#f4f0e6'],garnish:'#6fbf8f'},
  n:{fr:'Ciorbă de burtă',en:'Ciorbă de burtă'},
  p:{fr:'Bucarest, Roumanie',en:'Bucharest, Romania'},
  d:{fr:"Une soupe de tripes blanche et acidulée, liée au jaune d'œuf et à la crème, relevée d'ail et de vinaigre à table. Les Roumains la tiennent pour le remède souverain contre les lendemains difficiles.",
     en:"A white, sharp tripe soup thickened with egg yolk and cream, lifted with garlic and vinegar at the table. Romanians hold it to be the sovereign cure for a difficult morning after."},
  i:[['beef_tripe',1,'kg'],['veal_foot',1,'pc'],['carrot',3,'pc'],['celery_root',1,'pc'],['onion',2,'pc'],['garlic',10,'clove'],['egg_yolk',4,'pc'],['sour_cream',300,'ml'],['white_vinegar',80,'ml'],['bay_leaf',3,'pc'],['black_peppercorns',1,'tbsp'],['chili_pepper',2,'pc'],['salt',null,'']],
  s:{fr:["Nettoyez longuement les tripes au gros sel et au vinaigre, rincez-les à l'eau claire, puis blanchissez-les 10 minutes.","Faites-les cuire 2 h 30 avec le pied de veau, les légumes entiers, le laurier et le poivre, jusqu'à ce qu'elles soient tendres sous la fourchette.","Retirez les tripes, taillez-les en fines lanières et filtrez le bouillon.","Pilez l'ail avec un peu de sel et un peu de bouillon, puis versez cette liqueur dans la soupe.","Battez les jaunes avec la crème, détendez avec une louche de bouillon chaud et incorporez hors du feu. Servez avec vinaigre et piment à part."],
     en:["Clean the tripe thoroughly with coarse salt and vinegar, rinse it well, then blanch it for 10 minutes.","Cook it for 2½ hours with the veal foot, whole vegetables, bay and peppercorns, until tender to a fork.","Lift out the tripe, cut it into fine strips and strain the broth.","Pound the garlic with a little salt and a little broth, and stir this liquor into the soup.","Beat the yolks with the cream, loosen with a ladle of hot broth and stir in off the heat. Serve with vinegar and chilli on the side."]} },

{ id:'mici', c:'eu', lat:44.426, lon:26.100, base:6, prep:30, cook:15, diff:1, tags:['beef','grill','street'],
  art:{v:'board',bg:'#2b2419',plate:'#e8d8b8',style:'grill',food:['#8f3b2a','#c9754a','#e8d8b8','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Mici',en:'Mici'},
  p:{fr:'Bucarest, Roumanie',en:'Bucharest, Romania'},
  d:{fr:"De petits rouleaux de viande sans boyau, moelleux grâce au bicarbonate et à l'eau gazeuse, grillés partout où il y a une braise en Roumanie. On les mange avec de la moutarde et du pain, jamais avec des couverts.",
     en:"Small skinless meat rolls, made springy by bicarbonate and sparkling water, grilled wherever there are embers in Romania. Eaten with mustard and bread, never with cutlery."},
  i:[['ground_beef',700,'g'],['ground_lamb',300,'g'],['garlic',8,'clove'],['baking_soda',1,'tsp'],['sparkling_water',150,'ml'],['beef_broth',150,'ml'],['thyme',1,'tsp'],['allspice',1,'tsp'],['paprika',1,'tbsp'],['mustard',6,'tbsp'],['rustic_bread',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pilez l'ail avec un peu de sel et un peu de bouillon pour en tirer une eau parfumée.","Mêlez les viandes, les épices, le bicarbonate, l'eau d'ail et le bouillon, puis travaillez la masse 10 minutes.","Ajoutez l'eau gazeuse peu à peu : c'est elle qui donnera le moelleux caractéristique.","Laissez reposer une nuit au frais, puis formez des boudins de 8 cm à la poche à douille ou à la main mouillée.","Grillez 6 à 8 minutes sur braise vive en tournant souvent. Servez avec de la moutarde et du pain."],
     en:["Pound the garlic with a little salt and a little broth to draw out a fragrant liquid.","Mix the meats, spices, bicarbonate, garlic liquid and broth, then work the mass for 10 minutes.","Add the sparkling water little by little: it is what gives the characteristic springiness.","Rest overnight in the fridge, then pipe or shape 8 cm logs with wet hands.","Grill 6 to 8 minutes over lively embers, turning often. Serve with mustard and bread."]} },

{ id:'papanasi', c:'eu', lat:47.159, lon:27.587, base:4, prep:30, cook:15, diff:2, tags:['sweet','fry','cheese'],
  art:{v:'plate',bg:'#332a1e',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f4f0e6','#8f1a3a','#f2dfa8'],garnish:'#c9754a'},
  n:{fr:'Papanași',en:'Papanași'},
  p:{fr:'Iași, Moldavie roumaine',en:'Iași, Romanian Moldavia'},
  d:{fr:"Un beignet de fromage frais en forme d'anneau, coiffé de sa propre petite boule, noyé de crème aigre et de confiture de myrtilles. Le dessert de restaurant roumain par excellence, servi brûlant.",
     en:"A fresh cheese doughnut shaped like a ring, capped with its own little ball, drowned in sour cream and blueberry jam. The Romanian restaurant dessert par excellence, served scalding."},
  i:[['farmer_cheese',500,'g'],['egg',2,'pc'],['semolina',60,'g'],['flour',200,'g'],['baking_powder',1,'tsp'],['sugar',60,'g'],['lemon_zest',1,'pc'],['vanilla',1,'tsp'],['sour_cream',300,'ml'],['berry_jam',250,'g'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Égouttez le fromage frais une heure dans un linge : trop humide, la pâte boirait l'huile.","Mêlez-le aux œufs, au sucre, à la semoule, au zeste et à la vanille, puis ajoutez la farine et la levure sans trop travailler.","Laissez reposer 30 minutes, puis formez quatre anneaux de 10 cm et quatre petites boules.","Frites 3 minutes par face à 165 °C — pas plus chaud, sinon l'extérieur brunit avant que le cœur ne cuise.","Empilez l'anneau, la crème aigre, la confiture puis la boule, et servez immédiatement."],
     en:["Drain the fresh cheese for an hour in a cloth: too wet and the dough would drink the oil.","Mix it with the eggs, sugar, semolina, zest and vanilla, then add the flour and baking powder without overworking.","Rest for 30 minutes, then shape four 10 cm rings and four small balls.","Fry 3 minutes a side at 165°C — no hotter, or the outside browns before the centre cooks.","Stack the ring, sour cream, jam and then the ball, and serve at once."]} },

{ id:'kibinai', c:'eu', lat:54.639, lon:24.934, base:6, prep:60, cook:35, diff:2, tags:['bake','lamb','street'],
  art:{v:'board',bg:'#33291f',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#8f5a3a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Kibinai',en:'Kibinai'},
  p:{fr:'Trakai, Lituanie',en:'Trakai, Lithuania'},
  d:{fr:"Des chaussons de mouton apportés au XIVe siècle par les Karaïtes de Crimée, installés à Trakai par le grand-duc Vytautas. Six siècles plus tard, la communauté ne compte plus que quelques dizaines de personnes ; les kibinai, eux, sont partout en Lituanie.",
     en:"Mutton turnovers brought in the 14th century by the Crimean Karaites, settled at Trakai by Grand Duke Vytautas. Six centuries on, the community numbers only a few dozen; the kibinai, meanwhile, are all over Lithuania."},
  i:[['flour',600,'g'],['butter',250,'g'],['sour_cream',200,'ml'],['egg',3,'pc'],['mutton_shoulder',600,'g'],['lamb_fat',80,'g'],['onion',3,'pc'],['beef_broth',100,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Sablez la farine avec le beurre froid, ajoutez la crème aigre, un œuf et le sel, puis rassemblez sans pétrir. Réservez une heure au froid.","Hachez le mouton au couteau, en petits dés — jamais au robot, la texture ferait tout perdre.","Mêlez-le à l'oignon finement haché, au gras, au sel et à beaucoup de poivre.","Étalez la pâte, découpez des disques de 14 cm, garnissez et refermez en pinçant le bord en tresse.","Percez un petit trou sur le dessus, versez-y une cuillerée de bouillon, dorez à l'œuf et enfournez 35 minutes à 190 °C."],
     en:["Rub the cold butter into the flour, add the sour cream, one egg and the salt, and bring together without kneading. Chill for an hour.","Chop the mutton by knife into small dice — never in a processor, the texture would be lost.","Mix with finely chopped onion, the fat, salt and plenty of pepper.","Roll the pastry, cut 14 cm discs, fill them and seal the edge in a plaited crimp.","Pierce a small hole on top, pour in a spoonful of broth, glaze with egg and bake for 35 minutes at 190°C."]} },

{ id:'sklandrausis', c:'eu', lat:56.968, lon:21.973, base:8, prep:60, cook:30, diff:2, tags:['veg','bake','sweet'],
  art:{v:'plate',bg:'#33291f',plate:'#f2e6c8',style:'pastry',food:['#e0913a','#f2dfa8','#e8c46a','#c98a2c'],garnish:'#7fae6a'},
  n:{fr:'Sklandrausis',en:'Sklandrausis'},
  p:{fr:'Kuldīga, Courlande, Lettonie',en:'Kuldīga, Courland, Latvia'},
  d:{fr:"Une tartelette de seigle garnie de pomme de terre puis de carotte, sucrée au miel et parfumée au carvi. Venue des Lives, peuple finno-ougrien de la côte lettone dont il ne reste presque plus de locuteurs.",
     en:"A rye tartlet layered with potato then carrot, sweetened with honey and scented with caraway. It comes from the Livonians, a Finno-Ugric people of the Latvian coast whose language has almost no speakers left."},
  i:[['rye_flour',400,'g'],['butter',120,'g'],['warm_water',150,'ml'],['potato',500,'g'],['carrot',600,'g'],['heavy_cream',200,'ml'],['egg',2,'pc'],['honey',4,'tbsp'],['caraway',2,'tsp'],['salt',null,'']],
  s:{fr:["Pétrissez la farine de seigle, le beurre fondu, l'eau tiède et le sel : la pâte est sableuse et ne lève pas.","Étalez-la finement et foncez des cercles de 10 cm en relevant les bords à la main, comme une corbeille.","Écrasez les pommes de terre cuites avec un peu de crème, du sel et du carvi.","Faites de même avec les carottes cuites, en ajoutant le miel et un œuf.","Étalez d'abord la pomme de terre, puis la carotte, dorez à l'œuf et enfournez 30 minutes à 200 °C. Se mangent froides."],
     en:["Knead the rye flour, melted butter, warm water and salt: the dough is short and does not rise.","Roll it thin and line 10 cm rings, raising the edges by hand like a basket.","Mash the boiled potatoes with a little cream, salt and caraway.","Do the same with the boiled carrots, adding the honey and one egg.","Spread the potato first, then the carrot, glaze with egg and bake for 30 minutes at 200°C. Eaten cold."]} },

{ id:'kama-dessert', c:'eu', lat:59.437, lon:24.754, base:4, prep:15, cook:0, diff:1, tags:['sweet','fresh','fast'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'cake',food:['#c9a878','#f0e8d0','#8f6a4a','#e8dcc0'],garnish:'#8f1a3a'},
  n:{fr:'Kama au babeurre',en:'Kama with buttermilk'},
  p:{fr:'Tallinn, Estonie',en:'Tallinn, Estonia'},
  d:{fr:"Une farine de quatre céréales grillées — seigle, orge, avoine, pois — battue dans du babeurre et sucrée. Autrefois nourriture de voyage qui se conservait des mois, c'est aujourd'hui le goût d'enfance de tous les Estoniens.",
     en:"A flour of four roasted grains — rye, barley, oat and pea — beaten into buttermilk and sweetened. Once travelling food that kept for months, it is now the childhood taste of every Estonian."},
  i:[['kama_flour',150,'g'],['buttermilk',600,'ml'],['sour_cream',150,'ml'],['sugar',60,'g'],['honey',2,'tbsp'],['strawberries',250,'g'],['salt',null,'']],
  s:{fr:["Fouettez le babeurre avec la crème aigre jusqu'à ce que le mélange soit parfaitement lisse.","Versez la farine de kama en pluie fine, en fouettant sans arrêt : versée d'un coup, elle formerait des grumeaux impossibles à rattraper.","Sucrez au sucre et au miel, ajoutez une pincée de sel qui réveille les céréales grillées.","Laissez reposer 30 minutes au frais : la kama gonfle et la préparation épaissit d'elle-même.","Servez très frais dans des verres, avec des fraises coupées au fond et un filet de miel."],
     en:["Whisk the buttermilk with the sour cream until perfectly smooth.","Rain in the kama flour, whisking without pause: tipped in at once it forms lumps you will never recover from.","Sweeten with the sugar and honey, and add a pinch of salt that wakes up the roasted grain.","Rest for 30 minutes in the fridge: the kama swells and the mixture thickens by itself.","Serve very cold in glasses, with sliced strawberries at the bottom and a thread of honey."]} },

{ id:'verivorst', c:'eu', lat:58.386, lon:24.497, base:6, prep:60, cook:45, diff:3, tags:['pork','festive','bake'],
  art:{v:'board',bg:'#2b2419',plate:'#eee0bc',style:'grill',food:['#3a2a2a','#6f4a2a','#e8d8b8','#8f1a3a'],garnish:'#7fae6a'},
  n:{fr:'Verivorst',en:'Verivorst'},
  p:{fr:'Pärnu, Estonie',en:'Pärnu, Estonia'},
  d:{fr:"Le boudin de Noël estonien, à l'orge perlé plutôt qu'à l'oignon seul, servi avec de la confiture d'airelles et du chou braisé. On l'attend toute l'année : il n'apparaît en boutique qu'à partir de décembre.",
     en:"The Estonian Christmas blood sausage, made with pearl barley rather than onion alone, served with lingonberry jam and braised cabbage. It is waited for all year: it appears in shops only from December."},
  i:[['barley',400,'g'],['pork_blood',700,'ml'],['pork_fat',250,'g'],['onion',4,'pc'],['marjoram',2,'tbsp'],['allspice',2,'tsp'],['sausage_casings',2,'pc'],['lingonberry_jam',250,'g'],['sauerkraut',600,'g'],['butter',60,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire l'orge perlé à l'eau salée 25 minutes, puis égouttez-le et laissez-le tiédir.","Faites fondre le gras en dés et faites-y blondir les oignons finement hachés.","Mêlez l'orge, les oignons, le sang filtré, la marjolaine, le piment de la Jamaïque, le sel et beaucoup de poivre.","Embossez sans serrer — l'orge gonfle encore — et pochez 25 minutes dans une eau à 80 °C, en piquant les bulles.","Faites-les dorer 20 minutes au four à 200 °C et servez avec la confiture d'airelles et la choucroute braisée au beurre."],
     en:["Cook the pearl barley in salted water for 25 minutes, then drain and let it cool a little.","Render the diced fat and turn the finely chopped onions golden in it.","Mix the barley, onions, strained blood, marjoram, allspice, salt and plenty of pepper.","Fill the casings loosely — the barley swells further — and poach for 25 minutes in water at 80°C, pricking any bubbles.","Brown them in the oven for 20 minutes at 200°C and serve with lingonberry jam and butter-braised sauerkraut."]} },

{ id:'varenyky', c:'eu', lat:49.589, lon:34.551, base:6, prep:75, cook:15, diff:2, tags:['veg','comfort','sunday'],
  art:{v:'plate',bg:'#2f3328',plate:'#f4ecd8',style:'pastry',food:['#f0e8d0','#e8dcc0','#c9a878','#8fae7a'],garnish:'#7fae6a'},
  n:{fr:'Varenyky aux cerises',en:'Cherry varenyky'},
  p:{fr:'Poltava, Ukraine',en:'Poltava, Ukraine'},
  d:{fr:"Des raviolis de pâte molle farcis de griottes, servis avec de la crème et du sucre. Salés à la pomme de terre le reste de l'année, sucrés en juillet quand les cerisiers de Poltava croulent sous les fruits.",
     en:"Dumplings of soft dough filled with sour cherries, served with cream and sugar. Savoury with potato the rest of the year, sweet in July when the cherry trees of Poltava are heavy with fruit."},
  i:[['flour',500,'g'],['warm_water',250,'ml'],['egg',1,'pc'],['morello_cherries',700,'g'],['sugar',150,'g'],['potato_starch',2,'tbsp'],['sour_cream',300,'ml'],['butter',60,'g'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, l'eau tiède, l'œuf et le sel 10 minutes en une pâte souple ; laissez reposer 40 minutes sous un linge.","Dénoyautez les cerises et laissez-les dégorger une heure avec la moitié du sucre ; conservez le jus.","Égouttez-les et roulez-les dans la fécule : sans cela, le jus percerait la pâte à la cuisson.","Étalez la pâte à 2 mm, découpez des disques de 7 cm, garnissez de trois cerises et scellez soigneusement.","Pochez 4 minutes à l'eau frémissante, égouttez, roulez au beurre et servez avec la crème aigre, le sucre et le jus réduit."],
     en:["Knead the flour, warm water, egg and salt for 10 minutes into a supple dough; rest for 40 minutes under a cloth.","Stone the cherries and let them macerate for an hour with half the sugar; keep the juice.","Drain them and roll them in the starch: without it the juice would pierce the dough as it cooks.","Roll the dough to 2 mm, cut 7 cm discs, fill with three cherries each and seal carefully.","Poach for 4 minutes in simmering water, drain, toss in butter and serve with the sour cream, sugar and reduced juice."]} },

{ id:'salo-lviv', c:'eu', lat:49.840, lon:24.030, base:6, prep:30, cook:0, diff:1, tags:['pork','fresh','fast'],
  art:{v:'board',bg:'#2b2a1c',plate:'#f2e6c8',style:'flat',food:['#f4f0e6','#f0e8d0','#8f1a3a','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Salo à l’ail',en:'Garlic salo'},
  p:{fr:'Lviv, Ukraine',en:'Lviv, Ukraine'},
  d:{fr:"Du lard de dos salé au gros sel et à l'ail pendant une semaine, tranché finement sur du pain de seigle. Bien plus qu'un aliment en Ukraine : un symbole national dont Lviv possède un musée entier.",
     en:"Back fat cured for a week in coarse salt and garlic, sliced thinly onto rye bread. Far more than a food in Ukraine: a national symbol, to which Lviv devotes an entire museum."},
  i:[['pork_fat',1,'kg'],['coarse_salt',200,'g'],['garlic',12,'clove'],['black_peppercorns',2,'tbsp'],['bay_leaf',5,'pc'],['coriander_seeds',1,'tbsp'],['paprika',2,'tbsp'],['rye_bread',1,'pc'],['red_onion',1,'pc']],
  s:{fr:["Choisissez un lard de dos épais, à la couenne fine et à la chair d'un blanc nacré, sans veine de maigre.","Piquez-le d'éclats d'ail sur toute sa surface, à intervalles réguliers.","Frottez-le énergiquement d'un mélange de gros sel, poivre concassé, laurier émietté et coriandre.","Enveloppez-le d'un linge et laissez-le une semaine au réfrigérateur, en le retournant chaque jour.","Rincez, épongez, roulez dans le paprika et réservez au congélateur : c'est bien froid qu'il se tranche en voile. Servez sur pain de seigle avec de l'oignon cru."],
     en:["Choose thick back fat with a fine rind and pearly white flesh, with no streak of lean.","Stud it with slivers of garlic all over, at regular intervals.","Rub it hard with a mixture of coarse salt, cracked pepper, crumbled bay and coriander.","Wrap it in a cloth and leave it a week in the fridge, turning it daily.","Rinse, pat dry, roll in paprika and keep it in the freezer: it only slices paper-thin when very cold. Serve on rye bread with raw onion."]} },

{ id:'banosh', c:'eu', lat:48.923, lon:24.711, base:4, prep:10, cook:35, diff:2, tags:['veg','cheese','comfort'],
  art:{v:'pot',bg:'#33301f',plate:'#f4ecd8',style:'stew',food:['#f4f0e6','#e8c46a','#c9a878','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Banosh',en:'Banosh'},
  p:{fr:'Ivano-Frankivsk, Carpates, Ukraine',en:'Ivano-Frankivsk, Carpathians, Ukraine'},
  d:{fr:"La polenta des bergers houtsoules, cuite non pas à l'eau mais dans la crème aigre, jusqu'à ce que le beurre remonte à la surface. On la sert avec de la brynza et des grattons ; la tradition veut qu'un homme la remue.",
     en:"The polenta of Hutsul shepherds, cooked not in water but in sour cream, until the butter rises to the surface. Served with brynza and pork scratchings; tradition holds that a man should stir it."},
  i:[['cornmeal',250,'g'],['sour_cream',1,'l'],['bryndza_cheese',200,'g'],['pork_cracklings',150,'g'],['mushroom',200,'g'],['butter',40,'g'],['salt',null,'']],
  s:{fr:["Portez la crème aigre salée à frémissement dans un chaudron, sans jamais la laisser bouillir franchement.","Versez la semoule de maïs en pluie très fine en remuant en un seul sens, toujours le même.","Remuez sans interruption 25 minutes : la masse épaissit puis, brusquement, des gouttes de beurre remontent en surface. C'est le signe.","Retirez du feu aussitôt : quelques minutes de plus et le banosh graine irrémédiablement.","Servez dans le chaudron avec la brynza émiettée, les grattons et les champignons poêlés."],
     en:["Bring the salted sour cream to a bare simmer in a cauldron, never letting it boil properly.","Rain in the cornmeal very finely, stirring in one direction and always the same one.","Stir without pause for 25 minutes: the mass thickens then, suddenly, beads of butter rise to the surface. That is the sign.","Take it off the heat at once: a few minutes more and the banosh grains irretrievably.","Serve in the pot with the crumbled brynza, the scratchings and the fried mushrooms."]} },

{ id:'kotleta-po-kyivsky', c:'eu', lat:50.447, lon:30.530, base:4, prep:60, cook:20, diff:3, tags:['poultry','fry','festive'],
  art:{v:'plate',bg:'#2f3326',plate:'#f2e6c8',style:'pastry',food:['#e0b45a','#c98a2c','#f2dfa8','#6f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Côtelette à la Kyiv',en:'Chicken Kyiv'},
  p:{fr:'Kyiv, Ukraine',en:'Kyiv, Ukraine'},
  d:{fr:"Un blanc de poulet roulé autour d'un beurre d'herbes, pané et frit : à la découpe, le beurre fondu doit gicler. Toute la difficulté tient là — sceller assez pour qu'il ne s'échappe pas avant l'assiette.",
     en:"A chicken breast rolled around herb butter, breaded and fried: when cut, the melted butter should spurt out. The whole difficulty lies there — sealing it well enough that it does not escape before the plate."},
  i:[['chicken_breast',4,'pc'],['butter',200,'g'],['parsley',5,'tbsp'],['dill',3,'tbsp'],['garlic',4,'clove'],['lemon',1,'pc'],['flour',100,'g'],['egg',3,'pc'],['breadcrumbs',250,'g'],['frying_oil',1,'l'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Travaillez le beurre mou avec les herbes hachées, l'ail écrasé, le zeste de citron et le sel ; formez quatre boudins et faites-les durcir au congélateur.","Ouvrez les blancs en portefeuille et aplatissez-les entre deux feuilles jusqu'à 5 mm, sans percer.","Posez un boudin de beurre glacé au centre, repliez les côtés puis roulez serré ; filmez et raffermissez 30 minutes au froid.","Panez à l'anglaise deux fois — farine, œuf, chapelure, puis à nouveau œuf et chapelure : c'est la double couche qui retient le beurre.","Frites 8 minutes à 165 °C, puis 8 minutes au four à 180 °C. Servez immédiatement, la lame du couteau prête."],
     en:["Beat the soft butter with the chopped herbs, crushed garlic, lemon zest and salt; shape four logs and freeze them hard.","Butterfly the breasts and flatten them between two sheets to 5 mm, without piercing.","Set a frozen butter log at the centre, fold in the sides then roll tightly; wrap and firm up for 30 minutes in the fridge.","Bread them twice — flour, egg, crumb, then egg and crumb again: the double coat is what holds the butter.","Fry for 8 minutes at 165°C, then 8 minutes in the oven at 180°C. Serve immediately, knife at the ready."]} },

{ id:'machanka', c:'eu', lat:53.677, lon:23.829, base:4, prep:20, cook:45, diff:1, tags:['pork','comfort','breakfast'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#8f5a3a','#f0e8d0','#c9a878','#e8d8b8'],garnish:'#7fae6a'},
  n:{fr:'Machanka aux blinis',en:'Machanka with blini'},
  p:{fr:'Hrodna, Biélorussie',en:'Hrodna, Belarus'},
  d:{fr:"Un ragoût de porc à la crème dans lequel on trempe de grandes crêpes de sarrasin — machatsi veut dire « tremper ». Le petit-déjeuner du dimanche biélorusse, qui tient jusqu'au soir.",
     en:"A creamy pork stew into which large buckwheat pancakes are dipped — machatsi means 'to dip'. The Belarusian Sunday breakfast, which sees you through to the evening."},
  i:[['pork_belly',500,'g'],['smoked_sausage',200,'g'],['onion',2,'pc'],['sour_cream',400,'ml'],['flour',150,'g'],['buckwheat_flour',150,'g'],['whole_milk',400,'ml'],['egg',2,'pc'],['dry_yeast',5,'g'],['bay_leaf',2,'pc'],['lard',40,'g'],['dill',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Colorez le porc en gros dés et la saucisse dans le saindoux, ajoutez l'oignon et laissez fondre.","Mouillez d'un verre d'eau, ajoutez le laurier et laissez mijoter 35 minutes à couvert.","Délayez deux cuillerées de farine dans la crème aigre, versez dans la cocotte et laissez épaissir 5 minutes sans bouillir.","Pour les crêpes, mêlez les deux farines, le lait tiède, les œufs, la levure et le sel ; laissez lever 40 minutes.","Cuisez de grandes crêpes épaisses à la poêle et servez-les à côté du ragoût, pour y tremper. Parsemez d'aneth."],
     en:["Brown the pork in large dice and the sausage in the lard, add the onion and let it soften.","Moisten with a glass of water, add the bay and simmer covered for 35 minutes.","Slake two spoonfuls of flour in the sour cream, stir it into the pot and thicken for 5 minutes without boiling.","For the pancakes, mix both flours, the warm milk, eggs, yeast and salt; prove for 40 minutes.","Cook large thick pancakes in a pan and serve them beside the stew, for dipping. Scatter with dill."]} },

{ id:'zeama', c:'eu', lat:47.010, lon:28.863, base:6, prep:25, cook:75, diff:1, tags:['soup','poultry','comfort'],
  art:{v:'bowl',bg:'#2c3440',plate:'#f4ecd8',style:'soup',food:['#e8c46a','#f0e8d0','#c9a24a','#8fae7a'],garnish:'#6fbf8f'},
  n:{fr:'Zeamă',en:'Zeamă'},
  p:{fr:'Chișinău, Moldavie',en:'Chișinău, Moldova'},
  d:{fr:"Un bouillon de poule aux nouilles maison, acidulé au borș — un jus de son de blé fermenté, pas la betterave russe. La livèche est obligatoire : sans elle, disent les Moldaves, ce n'est pas une zeamă.",
     en:"A hen broth with home-made noodles, soured with borș — a fermented wheat bran liquor, not Russian beetroot. Lovage is compulsory: without it, Moldovans say, it is not a zeamă."},
  i:[['chicken',1.5,'kg'],['carrot',2,'pc'],['onion',2,'pc'],['bell_pepper',1,'pc'],['flour',250,'g'],['egg',2,'pc'],['lovage',1,'bunch'],['parsley',4,'tbsp'],['white_vinegar',60,'ml'],['ripe_tomato',2,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Portez la poule à frémissement dans trois litres d'eau froide et écumez patiemment pendant vingt minutes.","Ajoutez carotte, oignon et poivron entiers, et laissez cuire une heure sans bouillir.","Pendant ce temps, pétrissez la farine et les œufs en une pâte dure, étalez très finement et détaillez des nouilles fines ; laissez-les sécher sur un linge.","Retirez la volaille, désossez-la, filtrez le bouillon et remettez-le à frémir avec les tomates concassées.","Jetez-y les nouilles pour 5 minutes, remettez la viande, acidifiez au vinaigre et couvrez de livèche ciselée hors du feu."],
     en:["Bring the hen to a bare simmer in three litres of cold water and skim patiently for twenty minutes.","Add the whole carrot, onion and pepper, and cook for an hour without boiling.","Meanwhile knead the flour and eggs into a hard dough, roll it very thin and cut fine noodles; let them dry on a cloth.","Lift out the bird, bone it, strain the broth and return it to a simmer with the crushed tomatoes.","Drop in the noodles for 5 minutes, return the meat, sharpen with vinegar and cover with chopped lovage off the heat."]} }
];

